// Loads the sidebar, then fills in the most recent posts from /feed.xml.
// feed.xml is generated by build.js and already lists posts newest first.
document.addEventListener("DOMContentLoaded", () => {
    fetch("/sidebar.html?v=" + Date.now())
        .then(res => res.text())
        .then(html => {
            document.getElementById("sidebar").innerHTML = html;
            return fetch("/feed.xml");
        })
        .then(res => res.text())
        .then(xml => {
            const doc = new DOMParser().parseFromString(xml, "application/xml");
            const recent = [...doc.querySelectorAll("item")].slice(0, 3).map(item => ({
                title: item.querySelector("title").textContent,
                url: new URL(item.querySelector("link").textContent).pathname,
                date: new Date(item.querySelector("pubDate").textContent),
            }));

            const link = p => {
                const a = document.createElement("a");
                a.href = p.url;
                a.textContent = p.title;
                return a;
            };

            // Sidebar recent posts
            const sidebarList = document.getElementById("recent-posts");
            if (sidebarList) {
                sidebarList.replaceChildren(...recent.map(p => {
                    const li = document.createElement("li");
                    li.append(link(p));
                    return li;
                }));
            }

            // Homepage recent writing section (currently commented out in index.html)
            const mainList = document.getElementById("recent-posts-main");
            if (mainList) {
                mainList.replaceChildren(...recent.map(p => {
                    const li = document.createElement("li");
                    const date = document.createElement("span");
                    date.className = "post-date";
                    date.textContent = p.date.toLocaleDateString("en-US", { month: "short", year: "numeric", timeZone: "UTC" });
                    li.append(link(p), " ", date);
                    return li;
                }));
            }
        })
        .catch(err => console.error("Failed to load sidebar:", err));
});
